using System;using System.Reflection;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using Rootborn.UI.Interiors;namespace Rootborn.Tests.EditMode.Interiors{public sealed class FurniturePlacementLabelReadabilityTests{
GameObject root;[SetUp]public void SetUp(){root=new GameObject("PlacementLabelFixture",typeof(RectTransform));}[TearDown]public void TearDown(){UnityEngine.Object.DestroyImmediate(root);}static object Factory(string name,params object[] args)=>typeof(InteriorFurniturePlacementPanel).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);Text Label(Transform parent)=> (Text)Factory("CreateLabel",parent,"TestLabel","가구 검색",Vector2.zero,new Vector2(300,40),18);
[Test]public void OpeningPlacementPanelBringsItAboveEarlierHudSiblings(){var panelGo=new GameObject("Panel",typeof(RectTransform),typeof(InteriorFurniturePlacementPanel));panelGo.transform.SetParent(root.transform,false);panelGo.SetActive(false);var hud=new GameObject("Hud",typeof(RectTransform));hud.transform.SetParent(root.transform,false);panelGo.SetActive(true);typeof(InteriorFurniturePlacementPanel).GetMethod("OnEnable",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(panelGo.GetComponent<InteriorFurniturePlacementPanel>(),null);Assert.That(panelGo.transform.GetSiblingIndex(),Is.EqualTo(root.transform.childCount-1),"HUD shortcuts must not cover palette search when the panel opens");}
[Test]public void PaletteSearchTextLeavesRoomForTheDimensionalFrame(){var panel=root.AddComponent<InteriorFurniturePlacementPanel>();typeof(InteriorFurniturePlacementPanel).GetMethod("CreateFurnitureCategoryButtons",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(panel,new object[]{root.transform});var search=root.GetComponentsInChildren<InputField>().Single(i=>i.name=="FurniturePaletteSearchInput");var field=((RectTransform)search.transform).rect;var text=search.textComponent.rectTransform.rect;Assert.That(field.height-text.height,Is.GreaterThanOrEqualTo(32),"Keep sixteen logical pixels above/below text for the approved bevel");Assert.That(field.width-text.width,Is.GreaterThanOrEqualTo(32));}
[Test]public void InformationalLabelIsDarkOnApprovedCreamPanel(){var t=Label(root.transform);Assert.That(Mathf.Max(t.color.r,t.color.g,t.color.b),Is.LessThan(.35f),"Light panel information must not use pale button-label color");}
[Test]public void LabelsUseTheSharedKoreanCapableFont(){var t=Label(root.transform);var type=typeof(Rootborn.UI.StudentLife.CareerInterestPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont");var shared=(Font)type.GetProperty("Shared",BindingFlags.Public|BindingFlags.Static).GetValue(null);Assert.That(t.font,Is.SameAs(shared));}
[Test]public void DarkActionButtonRetainsLightLabel(){var b=new GameObject("Button",typeof(RectTransform),typeof(Image),typeof(Button));b.transform.SetParent(root.transform,false);var t=Label(b.transform);Assert.That(Mathf.Min(t.color.r,t.color.g,t.color.b),Is.GreaterThan(.75f));}
[Test]public void DarkInputAndDropdownRetainLightValues(){var input=(InputField)Factory("CreateInput",root.transform,"Input","123",Vector2.zero,new Vector2(300,40));var dropdown=(Dropdown)Factory("CreateDropdown",root.transform,"Dropdown",new[]{"북쪽"},0,Vector2.zero,new Vector2(300,40));Assert.That(Mathf.Min(input.textComponent.color.r,input.textComponent.color.g,input.textComponent.color.b),Is.GreaterThan(.75f));Assert.That(Mathf.Min(dropdown.captionText.color.r,dropdown.captionText.color.g,dropdown.captionText.color.b),Is.GreaterThan(.75f));}
}}
